public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public static Order parse(String body) {
        if (body == null || String.isBlank(body)) {
            throw new PayloadException('Request body is null or blank.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON.');
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('JSON body must be an object.');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        // --- number (required, non-blank) ---
        String orderNumber = getRequiredString(root, 'number');

        // --- date (optional, ISO yyyy-MM-dd) ---
        Date orderDate = null;
        Object dateVal = root.get('date');
        if (dateVal != null) {
            if (!(dateVal instanceof String)) {
                throw new PayloadException('Date field must be a string.');
            }
            try {
                orderDate = Date.parse((String) dateVal);
            } catch (Exception e) {
                throw new PayloadException('Invalid date format; expected yyyy-MM-dd.');
            }
        }

        // --- currency (optional) ---
        String currencyCode = null;
        Object currencyVal = root.get('currency');
        if (currencyVal instanceof String) {
            currencyCode = (String) currencyVal;
        }

        // --- customer (optional) ---
        String customerEmail = null;
        Object customerVal = root.get('customer');
        if (customerVal instanceof Map<String, Object>) {
            Map<String, Object> customerMap = (Map<String, Object>) customerVal;
            Object emailVal = customerMap.get('email');
            if (emailVal instanceof String) {
                customerEmail = (String) emailVal;
            }
        }

        // --- lines (optional, defaults to empty list) ---
        List<Line> lines = new List<Line>();
        Object linesVal = root.get('lines');
        if (linesVal != null) {
            if (!(linesVal instanceof List<Object>)) {
                throw new PayloadException('Lines must be an array.');
            }
            List<Object> linesList = (List<Object>) linesVal;
            for (Object item : linesList) {
                if (!(item instanceof Map<String, Object>)) {
                    throw new PayloadException('Each line must be a JSON object.');
                }
                lines.add(parseLine((Map<String, Object>) item));
            }
        }

        // --- total ---
        Decimal total = 0;
        for (Line line : lines) {
            total += line.lineTotal;
        }

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total;

        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>{
            'number'    => order.orderNumber,
            'status'    => 'RECEIVED',
            'lineCount' => order.lines.size(),
            'total'     => order.total
        };
        return JSON.serialize(ack);
    }

    // ---------- private helpers ----------

    private static Line parseLine(Map<String, Object> lineMap) {
        // sku – required
        Object skuVal = lineMap.get('sku');
        if (skuVal == null || !(skuVal instanceof String) || String.isBlank((String) skuVal)) {
            throw new PayloadException('Line is missing a valid sku.');
        }
        String sku = (String) skuVal;

        // quantity – required, positive integer
        Object qtyVal = lineMap.get('quantity');
        if (qtyVal == null) {
            throw new PayloadException('Line is missing quantity.');
        }
        Integer quantity;
        if (qtyVal instanceof Integer) {
            quantity = (Integer) qtyVal;
        } else if (qtyVal instanceof Decimal) {
            Decimal d = (Decimal) qtyVal;
            if (d != (Decimal) d.intValue()) {
                throw new PayloadException('Line quantity must be a whole number.');
            }
            quantity = d.intValue();
        } else {
            throw new PayloadException('Line quantity must be a number.');
        }
        if (quantity <= 0) {
            throw new PayloadException('Line quantity must be positive.');
        }

        // unitPrice – required, non-negative
        Object priceVal = lineMap.get('unitPrice');
        if (priceVal == null) {
            throw new PayloadException('Line is missing unitPrice.');
        }
        Decimal unitPrice;
        if (priceVal instanceof Integer) {
            unitPrice = (Decimal) (Integer) priceVal;
        } else if (priceVal instanceof Decimal) {
            unitPrice = (Decimal) priceVal;
        } else {
            throw new PayloadException('Line unitPrice must be a number.');
        }
        if (unitPrice < 0) {
            throw new PayloadException('Line unitPrice must not be negative.');
        }

        // discount – optional, defaults to 0
        Decimal discount = 0;
        Object discVal = lineMap.get('discount');
        if (discVal != null) {
            if (discVal instanceof Integer) {
                discount = (Decimal) (Integer) discVal;
            } else if (discVal instanceof Decimal) {
                discount = (Decimal) discVal;
            }
        }

        // lineTotal = quantity * unitPrice * (1 - discount), rounded half-up to 2 dp
        Decimal raw = (Decimal) quantity * unitPrice * (1 - discount);
        Decimal lineTotal = Math.round(raw * 100) / 100;

        Line line = new Line();
        line.sku = sku;
        line.quantity = quantity;
        line.unitPrice = unitPrice;
        line.discount = discount;
        line.lineTotal = lineTotal;
        return line;
    }

    private static String getRequiredString(Map<String, Object> source, String fieldName) {
        Object val = source.get(fieldName);
        if (val == null || !(val instanceof String) || String.isBlank((String) val)) {
            throw new PayloadException('Missing or blank required field: ' + fieldName);
        }
        return (String) val;
    }
}
