            throw new PicklistServiceException('Field API name cannot be null or blank.');
        }

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType sObjectType = null;

        for (String objName : globalDescribe.keySet()) {
            if (objName.equalsIgnoreCase(objectApiName)) {
                sObjectType = globalDescribe.get(objName);
                break;
            }
        }

        if (sObjectType == null) {
            throw new PicklistServiceException('Object not found: ' + objectApiName);
        }

        Schema.SObjectDescribe sObjectDescribe = sObjectType.getDescribe();
        Map<String, Schema.SObjectField> fieldMap = sObjectDescribe.fields.getMap();
        Schema.SObjectField sObjectField = null;

        for (String fieldName : fieldMap.keySet()) {
            if (fieldName.equalsIgnoreCase(fieldApiName)) {
                sObjectField = fieldMap.get(fieldName);
                break;
            }
        }

        if (sObjectField == null) {
            throw new PicklistServiceException('Field not found on object ' + objectApiName + ': ' + fieldApiName);
        }

        Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();

        if (fieldDescribe.getType() != Schema.DisplayType.PICKLIST
            && fieldDescribe.getType() != Schema.DisplayType.MULTISELECT_PICKLIST) {
            throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();

        List<Option> result = new List<Option>();
        for (Schema.PicklistEntry entry : entries) {
            if (entry.isActive()) {
                Option opt = new Option();
                opt.value = entry.getValue();
                opt.label = entry.getLabel();
                opt.isDefault = entry.isDefault();
                result.add(opt);
            }
        }

        return result;
    }
}
