public virtual class Opportunities extends fflib_SObjectDomain {

    private final List<SObject> sobjs;

    public static final fflib_SObjectDomain.IConstructable Constructor = new Constructor();

    public virtual class Constructor implements fflib_SObjectDomain.IConstructable {
        public virtual fflib_SObjectDomain construct(List<SObject> sobjs) {
            return new Opportunities(sobjs);
        }
    }

    public virtual Opportunities(List<SObject> sobjs) {
        super(sobjs, Opportunity.SObjectType);
        this.sobjs = sobjs;
    }

    public virtual void afterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (SObject sobj : sobjs) {
            Opportunity opp = (Opportunity) sobj;
            if (opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service =
                (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingIds);
        }
    }

    public virtual void afterUpdate() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (SObject sobj : sobjs) {
            Opportunity opp = (Opportunity) sobj;
            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
            if (opp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service =
                (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingIds);
        }
    }
}
