```apex
public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities();
        }
    }

    public override void onBeforeInsert(List<SObject> newRecords) {
        List<Opportunity> opps = (List<Opportunity>) newRecords;
        for (Opportunity opp : opps) {
            if (opp.Amount != null && opp.Amount < 0) {
                this.error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    public override void onBeforeUpdate(List<SObject> newRecords) {
        List<Opportunity> opps = (List<Opportunity>) newRecords;
        for (Opportunity opp : opps) {
            // Rule 1: Amount must not be negative
            if (opp.Amount != null && opp.Amount < 0) {
                this.error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
            // Rule 2: Amount cannot change on an already Closed Won opportunity
            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
            if (oldOpp.StageName == 'Closed Won' && opp.Amount != oldOpp.Amount) {
                this.error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
            }
        }
    }
}
