        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        // Dynamically include fields from the Credit_Review field set
        Schema.DescribeSObjectResult dsr = Account.SObjectType.getDescribe();
        Map<String, Schema.DescribeFieldSetResult> fieldSets = dsr.getFieldSets();
        if (fieldSets.containsKey('Credit_Review')) {
            Schema.DescribeFieldSetResult fs = fieldSets.get('Credit_Review');
            for (Schema.DescribeFieldSetResult.DisplayedField df : fs.getDisplayedFields()) {
                String fieldName = df.getFieldName();
                Schema.SObjectField field = dsr.fields.get(fieldName);
                if (!fields.contains(field)) {
                    fields.add(field);
                }
            }
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            fieldNames.add(field.getDescribe().getName());
        }

        String soql = 'WITH USER_MODE SELECT ' + String.join(fieldNames, ', ')
            + ' FROM Account WHERE Id IN :accountIds';

        return (List<Account>) Database.query(soql);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            fieldNames.add(field.getDescribe().getName());
        }

        // Build contact subquery fields from ContactsSelector
        ContactsSelector contactSelector = new ContactsSelector();
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField field : contactSelector.getSObjectFieldList()) {
            contactFieldNames.add(field.getDescribe().getName());
        }

        String soql = 'WITH USER_MODE SELECT ' + String.join(fieldNames, ', ')
            + ' FROM Account WHERE Id IN :accountIds'
            + ' AND (SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts)';

        return (List<Account>) Database.query(soql);
    }
}
