```apex
trigger AccountTrigger on Account (after insert) {
    List<Account> accounts = Trigger.new;
    Integer n = accounts.size();
    if (n == 0) return;

    // Limits: 50 queueable jobs enqueued per transaction,
    //         100 callouts per transaction (per queueable job).
    Integer MAX_CALLOUTS_PER_JOB = 100;
    Integer MAX_JOBS = 50;

    Integer jobsNeeded = (Integer) Math.ceil((Decimal) n / MAX_CALLOUTS_PER_JOB);
    if (jobsNeeded > MAX_JOBS) jobsNeeded = MAX_JOBS;
    if (jobsNeeded < 1) jobsNeeded = 1;

    Integer batchSize = (Integer) Math.ceil((Decimal) n / jobsNeeded);

    List<Account> batch = new List<Account>();
    for (Account acc : accounts) {
        batch.add(acc);
        if (batch.size() == batchSize || acc == accounts.last()) {
            System.enqueueJob(new ErpCustomerSync(batch));
            batch = new List<Account>();
        }
    }
}
