```apex
public class CaseSurveyJob implements Queueable {

    private static final Integer MAX_JOBS_PER_TX = 50;

    private Id       caseId;
    private List<Id> caseIds;

    /**
     * Single-case constructor – used by the trigger (and by the dispatcher).
     */
    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    /**
     * List constructor – used internally to chain when > 50 cases are eligible.
     */
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext ctx) {
        if (caseId != null) {
            processSingleCase(caseId);
        } else if (caseIds != null && !caseIds.isEmpty()) {
            dispatch(caseIds);
        }
    }

    // -----------------------------------------------------------------------
    // Dispatcher: enqueues up to (MAX_JOBS_PER_TX - 1) individual jobs plus
    // one more dispatcher for the remainder, keeping every transaction <= 50.
    // -----------------------------------------------------------------------
    private void dispatch(List<Id> ids) {
        if (ids.size() <= MAX_JOBS_PER_TX) {
            for (Id id : ids) {
                System.enqueueJob(new CaseSurveyJob(id));
            }
            return;
        }

        Integer chunkSize = MAX_JOBS_PER_TX - 1; // 49
        List<Id> firstChunk = new List<Id>();
        List<Id> remaining  = new List<Id>();

        for (Integer i = 0; i < ids.size(); i++) {
            if (i < chunkSize) {
                firstChunk.add(ids[i]);
            } else {
                remaining.add(ids[i]);
            }
        }

        for (Id id : firstChunk) {
            System.enqueueJob(new CaseSurveyJob(id));
        }

        // 49 individual + 1 dispatcher = 50 total (within the limit).
        System.enqueueJob(new CaseSurveyJob(remaining));
    }

    // -----------------------------------------------------------------------
    // Core work: create the CSAT survey Task for one Case.
    // -----------------------------------------------------------------------
    private void processSingleCase(Id cId) {
        Case theCase = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :cId
        ];

        // Re-check: the contact may have been removed after the trigger fired.
        if (theCase.ContactId == null) {
            return;
        }

        Task t = new Task(
            WhatId       = theCase.Id,
            WhoId        = theCase.ContactId,
            Subject      = 'CSAT survey: ' + theCase.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status       = 'Not Started'
        );

        insert t;
    }
}
