```apex
public class AccountCountrySync {

    public static void handle() {
        Map<Id, SObject> oldMap = Trigger.oldMap;
        List<Id> changedIds = new List<Id>();
        Map<Id, String> newCountry = new Map<Id, String>();
        Map<Id, String> oldCountry = new Map<Id, String>();

        for (SObject obj : Trigger.new) {
            Account acc = (Account) obj;
            Account oldAcc = (Account) oldMap.get(acc.Id);

            String prev = oldAcc.BillingCountry;
            String curr = acc.BillingCountry;

            if (curr != prev) {
                changedIds.add(acc.Id);
                newCountry.put(acc.Id, curr);
                oldCountry.put(acc.Id, prev);
            }
        }

        if (changedIds.isEmpty()) {
            return;
        }

        // One query: only contacts belonging to the changed accounts
        Map<Id, List<Contact>> contactsByAccount = new Map<Id, List<Contact>>();
        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedIds
        ]) {
            if (!contactsByAccount.containsKey(c.AccountId)) {
                contactsByAccount.put(c.AccountId, new List<Contact>());
            }
            contactsByAccount.get(c.AccountId).add(c);
        }

        // Build the update list
        List<Contact> toUpdate = new List<Contact>();
        for (Id accId : changedIds) {
            List<Contact> contacts = contactsByAccount.get(accId);
            if (contacts == null) {
                continue;
            }
            String newCty = newCountry.get(accId);
            String oldCty = oldCountry.get(accId);

            for (Contact c : contacts) {
                if (String.isBlank(c.MailingCountry) || c.MailingCountry == oldCty) {
                    toUpdate.add(new Contact(Id = c.Id, MailingCountry = newCty));
                }
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
