import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import * as confirmModule from 'lightning/confirm';
import { deleteRecord } from 'lightning/uiRecordApi';

// lightning/confirm exposes LightningConfirm as a named export in production,
// but in the test stub/mock it may be the default export. Handle both.
const LightningConfirm = confirmModule.LightningConfirm || confirmModule.default;

const COLUMNS = [
    { label: 'Name', fieldName: 'Name' },
    { label: 'Stage', fieldName: 'StageName' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @api opportunities = [];

    columns = COLUMNS;

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this._navigateToRecord(row.Id, 'view');
                break;
            case 'edit':
                this._navigateToRecord(row.Id, 'edit');
                break;
            case 'delete':
                this._handleDelete(row);
                break;
        }
    }

    _navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId: recordId,
                objectApiName: 'Opportunity',
                actionName: actionName
            }
        });
    }

    async _handleDelete(row) {
        const confirmed = await LightningConfirm.open({
            label: 'Delete Opportunity',
            message: 'Are you sure you want to delete this opportunity?',
            confirmLabel: 'Delete',
            cancelLabel: 'Cancel'
        });

        // If the user cancels, do nothing.
        if (!confirmed) {
            return;
        }

        try {
            await deleteRecord(row.Id);

            // Remove the row without mutating the parent's array.
            this.opportunities = this.opportunities.filter(
                (opp) => opp.Id !== row.Id
            );

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    message: `Opportunity "${row.Name}" has been deleted.`,
                    variant: 'success'
                })
            );
        } catch (error) {
            // Keep the row and surface the error.
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Delete failed',
                    message: error.body.message,
                    variant: 'error'
                })
            );
        }
    }
}
