public class FamilyService {

    /**
     * Creates NPSP "Parent" relationships for the given child→parent pairs.
     * NPSP's reciprocal (List Setting) logic automatically creates the
     * matching Son / Daughter / Child record on the parent side.
     *
     * @param parentIdByChildId  Keys = child Contact Ids, Values = parent Contact Ids.
     *                           Null or empty map is a no-op.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ---- Collect every Contact Id that appears in the input ----
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null) {
                allContactIds.add(childId);
                allContactIds.add(parentId);
            }
        }
        if (allContactIds.isEmpty()) {
            return;
        }

        // ---- Single SOQL: fetch every existing relationship touching any of
        //      those contacts, in either direction ----
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
                SELECT npe4__Contact__c, npe4__RelatedContact__c
                FROM npe4__Relationship__c
                WHERE npe4__Contact__c IN :allContactIds
                   OR npe4__RelatedContact__c IN :allContactIds
            ]) {
            if (rel.npe4__Contact__c != null && rel.npe4__RelatedContact__c != null) {
                existingPairKeys.add(buildPairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
            }
        }

        // ---- Build the list of new relationship records ----
        List<npe4__Relationship__c> newRels = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null) {
                continue;
            }

            // Skip if a relationship already exists in either direction
            String key = buildPairKey(childId, parentId);
            if (existingPairKeys.contains(key)) {
                continue;
            }

            // Mark as seen so duplicate pairs within the same call are skipped
            existingPairKeys.add(key);

            npe4__Relationship__c rel = new npe4__Relationship__c(
                npe4__Contact__c       = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c           = 'Parent',
                npe4__Status__c         = 'Current'
            );
            newRels.add(rel);
        }

        // ---- Single DML ----
        if (!newRels.isEmpty()) {
            insert newRels;
        }
    }

    /**
     * Returns a canonical (order-independent) key for an unordered pair of Ids.
     */
    private static String buildPairKey(Id a, Id b) {
        String sa = String.valueOf(a);
        String sb = String.valueOf(b);
        return sa <= sb ? sa + '|' + sb : sb + '|' + sa;
    }
}
