public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    override public npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();
        dmlWrapper.insertList = new List<SObject>();

        List<Opportunity> newOpps = (List<Opportunity>) newlist;
        List<Opportunity> oldOpps = (List<Opportunity>) oldlist;

        List<Task> tasks = new List<Task>();

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (Opportunity opp : newOpps) {
                if (isQualifyingMajorGift(opp)) {
                    tasks.add(buildTask(opp));
                }
            }
        } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            for (Integer i = 0; i < newOpps.size(); i++) {
                Opportunity newOpp = newOpps[i];
                Opportunity oldOpp = oldOpps[i];

                if (isQualifyingMajorGift(newOpp) && !isQualifyingMajorGift(oldOpp)) {
                    tasks.add(buildTask(newOpp));
                }
            }
        }

        if (!tasks.isEmpty()) {
            dmlWrapper.insertList.addAll(tasks);
        }

        return dmlWrapper;
    }

    private Boolean isQualifyingMajorGift(Opportunity opp) {
        return String.valueOf(opp.StageName) == 'Closed Won'
            && opp.Amount != null
            && opp.Amount >= 5000;
    }

