public class AccountOwnershipService {

    /**
     * Reassigns ownership of the given Accounts and all their Contacts to newOwnerId.
     * Account trigger actions are bypassed for the duration of the Account DML;
     * Contact trigger actions execute normally.
     *
     * @param accountIds  Up to 200 Account IDs to reassign.
     * @param newOwnerId  The User ID that will become the new owner.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Bypass all Account trigger actions for the remainder of this transaction.
        TriggerBase.bypass('Account');

        try {
            // --- DML 1: Update Accounts (trigger actions suppressed) ---
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accountId : accountIds) {
                accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }
            update accountsToUpdate;

            // --- SOQL 1: Fetch Contacts belonging to those Accounts ---
            List<Contact> contactsToUpdate = [
                SELECT Id
                FROM Contact
                WHERE AccountId IN :accountIds
                WITH USER_MODE
            ];

            // --- DML 2: Update Contacts (trigger actions run normally) ---
            for (Contact c : contactsToUpdate) {
                c.OwnerId = newOwnerId;
            }
            update contactsToUpdate;

        } finally {
            // Restore Account automation regardless of success or failure.
            TriggerBase.clearBypass('Account');
        }
    }
}
