public class TA_Case_RollupOpenCount implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    /**
     * After Insert: increment the open-case count for accounts that received
     * newly inserted open cases.
     */
    public void afterInsert(List<SObject> triggerNew) {
        List<Case> cases = (List<Case>) triggerNew;

        Map<Id, Integer> accountToOpenDelta = new Map<Id, Integer>();
        for (Case c : cases) {
            if (c.AccountId != null && !c.IsClosed) {
                accountToOpenDelta.put(c.AccountId,
                    accountToOpenDelta.getOrDefault(c.AccountId, 0) + 1);
            }
        }
        if (accountToOpenDelta.isEmpty()) {
            return;
        }

        Map<Id, Decimal> currentCounts = new Map<Id, Decimal>();
        for (Account acc : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountToOpenDelta.keySet()
        ]) {
            currentCounts.put(acc.Id,
                acc.FB_Open_Case_Count__c != null ? acc.FB_Open_Case_Count__c : 0);
        }

        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountToOpenDelta.keySet()) {
            toUpdate.add(new Account(
                Id = accId,
                FB_Open_Case_Count__c = currentCounts.get(accId) + accountToOpenDelta.get(accId)
            ));
        }
        update toUpdate;
    }

    /**
     * After Update: adjust the open-case count when IsClosed or AccountId changes.
     */
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Case> newCases = (List<Case>) triggerNew;
        List<Case> oldCases = (List<Case>) triggerOld;

        Map<Id, Integer> accountToDelta = new Map<Id, Integer>();

        for (Integer i = 0; i < newCases.size(); i++) {
            Case cNew = newCases[i];
            Case cOld = oldCases[i];

            if (cOld.AccountId != cNew.AccountId) {
                if (cOld.AccountId != null && !cOld.IsClosed) {
                    accountToDelta.put(cOld.AccountId,
                        accountToDelta.getOrDefault(cOld.AccountId, 0) - 1);
                }
                if (cNew.AccountId != null && !cNew.IsClosed) {
                    accountToDelta.put(cNew.AccountId,
                        accountToDelta.getOrDefault(cNew.AccountId, 0) + 1);
                }
            } else if (cNew.AccountId != null && cOld.IsClosed != cNew.IsClosed) {
                if (cNew.IsClosed) {
                    accountToDelta.put(cNew.AccountId,
                        accountToDelta.getOrDefault(cNew.AccountId, 0) - 1);
                } else {
                    accountToDelta.put(cNew.AccountId,
                        accountToDelta.getOrDefault(cNew.AccountId, 0) + 1);
                }
            }
        }

        List<Id> accountsToProcess = new List<Id>();
        for (Id accId : accountToDelta.keySet()) {
            if (accountToDelta.get(accId) != 0) {
                accountsToProcess.add(accId);
            }
        }
        if (accountsToProcess.isEmpty()) {
            return;
        }

        Map<Id, Decimal> currentCounts = new Map<Id, Decimal>();
        for (Account acc : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountsToProcess
        ]) {
            currentCounts.put(acc.Id,
                acc.FB_Open_Case_Count__c != null ? acc.FB_Open_Case_Count__c : 0);
        }

        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountsToProcess) {
            Decimal newCount = currentCounts.get(accId) + accountToDelta.get(accId);
            if (newCount < 0) {
                newCount = 0;
            }
            toUpdate.add(new Account(
                Id = accId,
                FB_Open_Case_Count__c = newCount
            ));
        }
        update toUpdate;
    }

    /**
     * After Delete: decrement the open-case count for accounts that lost open cases.
     */
    public void afterDelete(List<SObject> triggerOld) {
        List<Case> cases = (List<Case>) triggerOld;

        Map<Id, Integer> accountToOpenDelta = new Map<Id, Integer>();
        for (Case c : cases) {
            if (c.AccountId != null && !c.IsClosed) {
                accountToOpenDelta.put(c.AccountId,
                    accountToOpenDelta.getOrDefault(c.AccountId, 0) + 1);
            }
        }
        if (accountToOpenDelta.isEmpty()) {
            return;
        }

        Map<Id, Decimal> currentCounts = new Map<Id, Decimal>();
        for (Account acc : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountToOpenDelta.keySet()
        ]) {
            currentCounts.put(acc.Id,
                acc.FB_Open_Case_Count__c != null ? acc.FB_Open_Case_Count__c : 0);
        }

        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountToOpenDelta.keySet()) {
            Decimal newCount = currentCounts.get(accId) - accountToOpenDelta.get(accId);
            if (newCount < 0) {
                newCount = 0;
            }
            toUpdate.add(new Account(
                Id = accId,
                FB_Open_Case_Count__c = newCount
            ));
        }
        update toUpdate;
    }

    /**
     * After Undelete: increment the open-case count for accounts whose open cases
     * were restored.
     */
    public void afterUndelete(List<SObject> triggerNew) {
        List<Case> cases = (List<Case>) triggerNew;

        Map<Id, Integer> accountToOpenDelta = new Map<Id, Integer>();
        for (Case c : cases) {
            if (c.AccountId != null && !c.IsClosed) {
                accountToOpenDelta.put(c.AccountId,
                    accountToOpenDelta.getOrDefault(c.AccountId, 0) + 1);
            }
        }
        if (accountToOpenDelta.isEmpty()) {
            return;
        }

        Map<Id, Decimal> currentCounts = new Map<Id, Decimal>();
        for (Account acc : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountToOpenDelta.keySet()
        ]) {
            currentCounts.put(acc.Id,
                acc.FB_Open_Case_Count__c != null ? acc.FB_Open_Case_Count__c : 0);
        }

        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountToOpenDelta.keySet()) {
            toUpdate.add(new Account(
                Id = accId,
                FB_Open_Case_Count__c = currentCounts.get(accId) + accountToOpenDelta.get(accId)
            ));
        }
        update toUpdate;
    }
