public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    private static Set<Id> processedThisTransaction = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Task> tasksToCreate = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = (Opportunity) triggerNew[i];
            Opportunity oldOpp = (Opportunity) triggerOld[i];

            // Skip re-entries (e.g., caused by the rounding action's DML)
            if (processedThisTransaction.contains(newOpp.Id)) {
                continue;
            }
            processedThisTransaction.add(newOpp.Id);

            // Only create a task when the user's update actually changed the Amount
            if (newOpp.Amount != oldOpp.Amount) {
                tasksToCreate.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = newOpp.Id,
                    Status = 'Completed'
                ));
            }
        }

        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }
    }
}
